const envelope = $('When Executed by Another Workflow').first().json;
let data = $input.first().json;
if (data && typeof data.output === 'object' && !Array.isArray(data.output)) data = data.output;

function fail(message) {
  throw new Error(`[overall] ${message}`);
}
function isObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function requireExactKeys(object, required) {
  if (!isObject(object)) fail('Output must be one JSON object.');
  const actual = Object.keys(object);
  const missing = required.filter((key) => !(key in object));
  const extra = actual.filter((key) => !required.includes(key));
  if (missing.length) fail(`Missing keys: ${missing.join(', ')}`);
  if (extra.length) fail(`Unexpected keys: ${extra.join(', ')}`);
}

const required = [
  'determination','employee_satisfaction','salary_competitiveness',
  'remote_work_flexibility','skills_alignment','cultural_fit','explanation'
];
requireExactKeys(data, required);
if (!['yes','no'].includes(data.determination)) fail('determination must be "yes" or "no".');
if (typeof data.explanation !== 'string' || data.explanation.trim() === '') fail('explanation must be a non-empty string.');
if (data.explanation.length > 280) fail('explanation exceeds 280 characters.');
if (/[\r\n]/.test(data.explanation)) fail('explanation must not contain literal line breaks.');

const dimensions = ['employee_satisfaction','salary_competitiveness','remote_work_flexibility','skills_alignment','cultural_fit'];
for (const key of dimensions) {
  const value = data[key];
  if (value !== null && (!Number.isInteger(value) || value < 1 || value > 5)) fail(`${key} must be null or an integer from 1 through 5.`);
}

const preferences = envelope.results?.preferences || {};
const skills = envelope.results?.skills || {};
const eligibilityConfirmed = Array.isArray(preferences.preference_matches) && preferences.preference_matches.some((entry) => entry.startsWith('[ELIGIBILITY] Confirmed:'));
const veto = Number(preferences.preferences_rating) === 0 || !eligibilityConfirmed;
const allNull = dimensions.every((key) => data[key] === null);

if (veto) {
  if (!allNull || data.determination !== 'no') fail('Preference or eligibility veto requires all dimensions null and determination "no".');
  return [{ json: data }];
}

if (allNull) {
  if (data.determination !== 'no') fail('All-null dimensions require determination "no".');
  return [{ json: data }];
}

if (data.remote_work_flexibility === null || data.skills_alignment === null) fail('Any scored result must include remote_work_flexibility and skills_alignment.');
if (data.skills_alignment !== Number(skills.skill_rating)) fail('skills_alignment must exactly copy the validated skill_rating.');

const weights = {
  employee_satisfaction: 0.25,
  salary_competitiveness: 0.25,
  remote_work_flexibility: 0.20,
  skills_alignment: 0.20,
  cultural_fit: 0.10,
};
const present = dimensions.filter((key) => data[key] !== null);
const weightSum = present.reduce((sum, key) => sum + weights[key], 0);
if (weightSum < 0.65) fail(`Supported base weight ${weightSum.toFixed(2)} is below the 0.65 minimum.`);
const weighted = present.reduce((sum, key) => sum + data[key] * weights[key], 0) / weightSum;
const rounded = Math.round(weighted * 10) / 10;
const expectedDetermination = rounded >= 3.0 ? 'yes' : 'no';
if (data.determination !== expectedDetermination) fail(`determination must be "${expectedDetermination}" for weighted score ${rounded.toFixed(1)}.`);

return [{ json: data }];

const envelope = $('When Executed by Another Workflow').first().json;
const analysis = $input.first().json;
const jobId = String(envelope.job?.job_id || '').trim();
if (!/^\d{6,20}$/.test(jobId)) throw new Error('[overall] Missing canonical LinkedIn job_id.');
const result = { ...analysis, job_id: jobId };
return [{
  json: {
    ...envelope,
    results: { ...(envelope.results || {}), overall: result },
  },
}];
